void main() => runApp(const StyleSyncApp());

class StyleSyncApp extends StatefulWidget {
  const StyleSyncApp({super.key});
  @override State<StyleSyncApp> createState() => _StyleSyncAppState();
}
class _StyleSyncAppState extends State<StyleSyncApp> {
  String? token;
  String apiBase = apiDefault;
  bool loading = true;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { final p = await SharedPreferences.getInstance(); setState(() { token=p.getString('token'); apiBase=p.getString('apiBase') ?? apiDefault; loading=false; }); }
  Future<void> _login(String t, String base) async { final p=await SharedPreferences.getInstance(); await p.setString('token',t); await p.setString('apiBase',base); setState(() {token=t; apiBase=base;}); }
  Future<void> _logout() async { final p=await SharedPreferences.getInstance(); await p.remove('token'); setState(()=>token=null); }
  @override Widget build(BuildContext context) => MaterialApp(
    title:'StyleSync AI', debugShowCheckedModeBanner:false,
    theme: ThemeData(useMaterial3:true, colorScheme: ColorScheme.fromSeed(seedColor:brand, brightness:Brightness.light), scaffoldBackgroundColor:const Color(0xFFF7F7FC), appBarTheme:const AppBarTheme(backgroundColor:Color(0xFFF7F7FC), foregroundColor:ink, elevation:0), cardTheme:CardThemeData(color:Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20))), inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14),borderSide:BorderSide.none),contentPadding:const EdgeInsets.all(16))),
    home: loading ? const Scaffold(body:Center(child:CircularProgressIndicator())) : token==null ? AuthScreen(apiBase:apiBase,onSuccess:_login) : HomeScreen(apiBase:apiBase,token:token!,onLogout:_logout));
}

class Api {
 final String base, token; Api(this.base,this.token);
 Map<String,String> get headers=>{'Content-Type':'application/json','Authorization':'Bearer $token'};
 Future<dynamic> get(String path) async { final r=await http.get(Uri.parse('$base$path'),headers:headers).timeout(const Duration(seconds:20)); return _decode(r); }
 Future<dynamic> post(String path, Map<String,dynamic> data) async { final r=await http.post(Uri.parse('$base$path'),headers:headers,body:jsonEncode(data)).timeout(const Duration(seconds:30)); return _decode(r); }
 Future<dynamic> _decode(http.Response r) { final d=r.body.isEmpty?null:jsonDecode(r.body); if(r.statusCode<200||r.statusCode>=300) throw Exception(d is Map ? (d['error']??'Request failed (${r.statusCode})') : 'Request failed (${r.statusCode})'); return Future.value(d); }
}

